}

def tree_sum(node):
    if node is None:
        return 0                        # an empty tree adds nothing
    left = tree_sum(node.left)          # ask the left subtree for its total
    right = tree_sum(node.right)        # ask the right subtree for its total
    return node.val + left + right      # combine: me + both answers

