function sumIterative(root) {
  if (root === null) return 0;
  let total = 0;
  const stack = [root];                 // nodes still to visit
  while (stack.length > 0) {
    const node = stack.pop();
    total += node.val;
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return total;
}

def sum_iterative(root):
    if root is None:
        return 0
    total = 0
    stack = [root]                      # nodes still to visit
    while stack:
        node = stack.pop()
        total += node.val
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return total

int sumIterative(TreeNode root) {
    if (root == null) return 0;
    int total = 0;
    Deque<TreeNode> stack = new ArrayDeque<>();   // nodes still to visit
    stack.push(root);
    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();
        total += node.val;
        if (node.left != null) stack.push(node.left);
        if (node.right != null) stack.push(node.right);
    }
    return total;
}

int sumIterative(TreeNode* root) {
    if (root == nullptr) return 0;
    int total = 0;
    stack<TreeNode*> st;                // nodes still to visit
    st.push(root);
    while (!st.empty()) {
        TreeNode* node = st.top();
        st.pop();
        total += node->val;
        if (node->left) st.push(node->left);
        if (node->right) st.push(node->right);
    }
    return total;
}
